 "서명 비밀값 (받는 쪽에서 진짜 알림인지 확인할 때 써요. 지금만 보여요.)": "署名シークレット(受け取る側が本物の通知かどうか確認するときに使います。今だけ表示されます。)",
 "알림에 기억 내용도 넣기 (비공개·비밀 표시된 내용은 빼요)": "通知に記憶の内容も含める(非公開・シークレットの内容は除きます)",
 "웹훅 추가": "Webhookを追加",
 "https://로 시작하는 주소를 넣어 주세요.": "https:// で始まるアドレスを入力してください。",
 "알림 보낼 때를 하나 이상 골라 주세요.": "通知を送るタイミングを1つ以上選んでください。",
 "웹훅을 추가했어요. '시험 보내기'로 확인해 보세요.": "Webhookを追加しました。「テスト送信」で確認してみてください。",
 "이 서버는 아직 웹훅을 지원하지 않아요. 서버를 새 버전으로 올려 주세요.": "このサーバーはまだWebhookに対応していません。サーバーを新しいバージョンに更新してください。",
 "웹훅은 사람 계정으로 로그인했을 때만 보고 바꿀 수 있어요.": "Webhookは、人のアカウントでログインしているときだけ表示・変更できます。",
 "작업 공간과 프로젝트가 정해지지 않았어요. 설정 › 고급 › 연결에서 범위를 먼저 정해 주세요.": "ワークスペースとプロジェクトが決まっていません。設定 › 詳細 › 接続で、先に範囲を決めてください。",
 "기억 후보가 생기거나 기억이 승인·변경될 때 다른 서비스로 알림을 보내요.": "記憶候補ができたときや、記憶が承認・変更されたときに、ほかのサービスへ通知を送ります。",
