 "기억을 승인했을 때": "記憶を承認したとき",
 "기억을 버렸을 때": "記憶を破棄したとき",
 "기억이 바뀌었을 때": "記憶が変更されたとき",
 "기억을 지웠을 때": "記憶を削除したとき",
 "기억 정리가 끝났을 때": "記憶の整理が終わったとき",
 "파일 수집이 끝났을 때": "ファイルの取り込みが終わったとき",
 "공간 방어 규칙이 작동했을 때": "スペースの防御ルールが働いたとき",
 "시험 알림": "テスト通知",
 "보냄": "送信済み",
