 "에이전트(Claude Code·Codex·Gemini CLI)를 연결하면 요청이 라우터를 거쳐 알맞은 모델로 가고, 여기에 요청 수·응답 시간·비용이 나와요.": "エージェント(Claude Code・Codex・Gemini CLI)を接続すると、リクエストがルーターを通って適したモデルに送られ、ここにリクエスト数・応答時間・コストが表示されます。",
