 "꺼져 있어요. 모든 요청이 기본 모델로 가요.": "オフです。すべてのリクエストが基本モデルに送られます。",
 "켜져 있지만 판정 모델이 없어요.": "オンですが、判定モデルがありません。",
 "기본 모델 (자동 라우팅을 껐거나 판정 모델이 고르지 못할 때)": "基本モデル(自動ルーティングがオフのとき、または判定モデルが選べないとき)",
 "고른 모델이 답을 시작하기 전에 거절되면 바로 다음 모델로 넘겨요. 답을 쓰던 중에 끊긴 요청은 넘기지 않아요.": "選ばれたモデルが応答を始める前に拒否されると、すぐ次のモデルに回します。応答の途中で切れたリクエストは回しません。",
 "1번 모델부터 차례로": "1番モデルから順に",
 "한도나 크레딧이 떨어져 거절된 모델은 잠시 쉬며 맨 뒤로 가요. 요청 하나로 먼저 확인한 뒤 돌아와요.": "上限やクレジットが尽きて拒否されたモデルは、しばらく休んで最後尾に回ります。リクエストを1回試して確認してから戻ります。",
