 "요청에 든 낱말로 일의 종류를 알아보고, 정한 모델로 바로 보내요. 판정 모델보다 먼저 쓰고, 자동 라우팅이 켜져 있을 때만 써요.": "リクエストに含まれる言葉から作業の種類を見分けて、決めたモデルにそのまま送ります。判定モデルより先に使い、自動ルーティングがオンのときだけ使います。",
