 "평가 서버가 평가 설정을 보내지 않았어요. 평가 서버의 Arkism 설정을 확인해 주세요.": "評価サーバーから評価設定が送られてきませんでした。評価サーバーのArkismの設定を確認してください。",
 "평가 서버에 등록된 평가 과제가 없어요. 평가 서버 설정에 과제를 하나 등록하면 자동으로 채워져요.": "評価サーバーに登録された評価課題がありません。評価サーバーの設定に課題を1つ登録すると、自動で入力されます。",
