 "이 앱 버전에 맞는 서버 묶음이 릴리스에 없어요.": "このアプリのバージョンに合うサーバーパッケージがリリースにありません。",
 "서버의 CPU 종류(아키텍처)용 묶음이 없어요. Linux x86_64·arm64만 지원해요.": "サーバーのCPUの種類(アーキテクチャ)用のパッケージがありません。Linux x86_64とarm64のみ対応しています。",
 "내려받은 서버 묶음의 서명이 맞지 않아 설치하지 않았어요.": "ダウンロードしたサーバーパッケージの署名が一致しないため、インストールしませんでした。",
