 "서버에서 Arkism 설치 폴더를 찾지 못했어요.": "サーバーでArkismのインストールフォルダーが見つかりませんでした。",
 "설치 폴더에 쓸 권한이 없어요. 서버에서 이 SSH 사용자에게 폴더 쓰기 권한을 주거나, 비밀번호 없는 sudo(sudo -n)를 허용해 주세요.": "インストールフォルダーに書き込む権限がありません。サーバーでこのSSHユーザーにフォルダーの書き込み権限を付与するか、パスワードなしのsudo(sudo -n)を許可してください。",
 "서비스를 다시 시작하려면 sudo가 필요해요. 이 SSH 사용자에게 비밀번호 없는 sudo(sudo -n)를 허용하거나, 서버에서 직접 업데이트해 주세요.": "サービスを再起動するにはsudoが必要です。このSSHユーザーにパスワードなしのsudo(sudo -n)を許可するか、サーバー上で直接更新してください。",
 "Arkism 서버를 돌리는 systemd 서비스를 찾지 못했어요. 서버를 서비스로 띄운 뒤 다시 시도하거나, 직접 업데이트해 주세요.": "Arkismサーバーを動かしているsystemdサービスが見つかりませんでした。サーバーをサービスとして起動してからもう一度試すか、直接更新してください。",
