 "새 서버가 정상으로 뜨지 않아 예전 버전으로 되돌렸어요. DB 구조 변경이 필요하면 서버에서 memoryd --init-db를 먼저 실행하세요.": "新しいサーバーが正常に起動しなかったため、以前のバージョンに戻しました。DB構造の変更が必要な場合は、先にサーバーでmemoryd --init-dbを実行してください。",
