 "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "人の名前やメールアドレスなど消したい言葉を入力すると、その言葉を含む記憶と元の記録をすべて探して完全に削除します。先に件数をお見せします。",
