 "Arkism 서버에 로그인": "Arkismサーバーにログイン",
 "서버 관리자에게 받은 접속 토큰을 붙여 넣으세요. 토큰은 이 브라우저 탭에만 두고, 탭을 닫으면 지워져요.": "サーバー管理者から受け取ったアクセストークンを貼り付けてください。トークンはこのブラウザーのタブにだけ保存され、タブを閉じると消えます。",
 "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "アドレスを確認してください。user@サーバーのアドレス または user@サーバーのアドレス:ポート のように入力します。",
 "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "このPCで ssh プログラムが見つかりませんでした。OpenSSH(または Git for Windows)をインストールしてください。",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "SSHログインが拒否されました。このPCで「ssh アドレス」がパスワードなし(SSHキー)で通るか確認してください。",
 "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "サーバーに届きませんでした。アドレス・ポートとネットワーク接続を確認してください。",
 "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "サーバーにはログインできましたが、Arkismがインストールされていません。",
