 "노드를 누르면 여기서 고쳐요. 출력 점을 끌어 다음 노드에 이어요. 앞 노드로 이으면 되돌아가는 선이 돼요. 선을 누르면 선 설정이 열려요. 휠로 확대·축소하고, 휠 클릭이나 스페이스를 누른 채 끌면 화면이 움직여요.": "ノードをクリックすると、ここで編集できます。出力の点をドラッグして次のノードにつなぎます。前のノードにつなぐと戻る線になります。線をクリックすると線の設定が開きます。ホイールで拡大・縮小でき、ホイールクリックまたはスペースを押したままドラッグすると画面が動きます。",
