 "발표·보고용 슬라이드 프롬프트와 만드는 스크립트를 모아 둬요. 카드를 고르면 오른쪽에서 고치고 바로 만들 수 있어요.": "発表・報告用のスライドプロンプトと、作成用スクリプトをまとめています。カードを選ぶと、右側で編集してすぐに作成できます。",
