 "질문할 때 찾아 넣은 기억의 문구가 답에 보였는지만 세요. 실제 활용 여부는 측정하지 않았고, 읽지 못한 대화 수는 이 통계에서 알 수 없어요.": "質問のときに探して入れた記憶の文言が、回答に表れたかどうかだけを数えます。実際に活用されたかは測定しておらず、読み取れなかった会話の数はこの統計ではわかりません。",
