 "전달한 기억 중 답에 보인 비율": "渡した記憶のうち回答に表れた割合",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보여요. 직접 확인해 주세요": "再確認の予定日を過ぎているか、最近あまり呼び出されていないか、回答にあまり表れていません。ご自身で確認してください",
 "승인 기록": "承認記録",
 "재검토 예정일이 지났거나 최근에 잘 안 불리거나 답에 잘 안 보이는 기억이에요. 실제 활용 여부와는 구분해요.": "再確認の予定日を過ぎているか、最近あまり呼び出されていないか、回答にあまり表れていない記憶です。実際に活用されたかどうかとは区別しています。",
