 "각 문장의 조건과 예외를 확인하고 항목별로 결정해 주세요.": "各文の条件と例外を確認して、項目ごとに決めてください。",
 "원문 근거를 확인하는 중…": "原文の根拠を確認しています…",
 "재검토 예정일이 지났어요": "再確認の予定日を過ぎました",
