 "이 PC에서 Arkism을 실행해요. 인터넷 없이도 되고, 기억은 이 PC에만 저장돼요.": "このPCでArkismを実行します。インターネットなしでも使えて、記憶はこのPCだけに保存されます。",
 "서버에서 돌고 있는 Arkism을 SSH로 이어요. 여러 PC가 같은 기억을 써요.": "サーバーで動いているArkismにSSHでつなぎます。複数のPCで同じ記憶を使えます。",
 "Arkism을 어디서 쓸까요?": "Arkismをどこで使いますか?",
 "처음 한 번만 고르면 돼요. 나중에 설정 › 연결에서 바꿀 수 있어요.": "最初に1回選ぶだけです。あとで設定 › 接続で変更できます。",
