 "폴더 경로를 넣어 주세요.": "フォルダーのパスを入力してください。",
 "C:\\ 나 /로 시작하는 전체 경로를 넣어 주세요.": "C:\\ または / で始まるフルパスを入力してください。",
 "파일이 아니라 폴더 경로를 넣어 주세요.": "ファイルではなく、フォルダーのパスを入力してください。",
 "빈 폴더나 Arkism 데이터 폴더만 쓸 수 있어요.": "空のフォルダーか、Arkismのデータフォルダーのみ使用できます。",
 "이 폴더를 읽을 수 없어요.": "このフォルダーを読み取れません。",
 "이 폴더에 쓸 수 없어요. 권한을 확인해 주세요.": "このフォルダーに書き込めません。権限を確認してください。",
 "저장 위치를 바꿨어요.": "保存場所を変更しました。",
 "앱을 다시 열면 새 위치에서 시작해요.": "アプリをもう一度開くと、新しい場所で始まります。",
 "저장 위치를 읽지 못했어요.": "保存場所を読み取れませんでした。",
 "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요. 키가 없으면 인증 방식을 비밀번호로 바꾸세요.": "SSHログインが拒否されました。このPCで「ssh アドレス」がパスワードなし(SSHキー)で通るか確認してください。キーがない場合は、認証方式をパスワードに変更してください。",
 "비밀번호 로그인이 거부됐어요. 비밀번호를 확인하세요. 서버가 비밀번호 로그인을 막아 두었으면 SSH 키가 필요해요.": "パスワードでのログインが拒否されました。パスワードを確認してください。サーバーがパスワードログインを禁止している場合は、SSHキーが必要です。",
 "비밀번호 로그인이 거부됐어요": "パスワードでのログインが拒否されました",
