 "인증 방식": "認証方式",
 "SSH 키": "SSHキー",
 "비밀번호": "パスワード",
 "연결되면 이 PC의 키체인(자격 증명 관리자)에 저장해 다시 묻지 않아요. 비워 두면 저장된 비밀번호를 써요": "接続できると、このPCのキーチェーン(資格情報マネージャー)に保存され、次からは聞かれません。空のままにすると、保存済みのパスワードを使います",
 "서버의 Git·스킬 화면은 이 연결로 돼요. 에이전트의 기억 수집은 SSH 키가 있어야 서버로 가요.": "サーバーのGitやスキルの画面は、この接続を使います。エージェントの記憶の収集は、SSHキーがあるときだけサーバーに届きます。",
 "SSH 키 또는 ssh-agent로 로그인해요": "SSHキーまたはssh-agentでログインします",
 "저장된 비밀번호가 없어요. 비밀번호를 넣고 연결하세요.": "保存されたパスワードがありません。パスワードを入力して接続してください。",
 "SSH 키 또는 비밀번호로 접속해요. 비밀번호는 이 PC의 키체인에 저장해 다시 묻지 않고, 연결 끊기를 누르면 지금 연결된 서버의 비밀번호를 지워요.": "SSHキーまたはパスワードで接続します。パスワードはこのPCのキーチェーンに保存され、次からは聞かれません。「接続を切る」を押すと、今つながっているサーバーのパスワードを削除します。",
 "이 PC의 터미널에서 아래 명령으로 같은 비밀번호로 접속되는지 먼저 확인하세요.": "このPCのターミナルで、下のコマンドを使って同じパスワードで接続できるか、まず確認してください。",
