 "서버가 분석 요청을 거부했어요. 에이전트 로그인을 확인해 주세요.": "サーバーが分析リクエストを拒否しました。エージェントのログインを確認してください。",
 "최근 2시간 동안 서버의 분석이 돌지 않았어요. 서버에서 분석 타이머를 켜 주세요.": "直近2時間、サーバーで分析が実行されていません。サーバーで分析タイマーをオンにしてください。",
